package com.gameaggregator.apikeyservice.application;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;class ApiKeyHasherTest{@Test void hashesDeterministicallyWithoutPersistingRawSecret(){var h=new ApiKeyHasher("01234567890123456789012345678901");String raw="gak_live_prefix_raw-secret";assertThat(h.hash(raw)).hasSize(64).isEqualTo(h.hash(raw)).doesNotContain(raw);}@Test void pepperChangesHash(){String raw="gak_live_prefix_raw-secret";assertThat(new ApiKeyHasher("01234567890123456789012345678901").hash(raw)).isNotEqualTo(new ApiKeyHasher("abcdefghijklmnopqrstuvwxyz123456").hash(raw));}}